function updateXaiSim() {
  const pop = parseInt(document.getElementById('simPopSlider').value, 10);
  const sens = parseInt(document.getElementById('simSensSlider').value, 10);
  const threat = parseInt(document.getElementById('simThreatSlider').value, 10);
  const total = pop + sens + threat + 9; // baseline 9

  const scoreOutOfTen = (total / 10).toFixed(1);
  const scoreEl = document.getElementById('simTotalScore');
  const badgeEl = document.getElementById('simSeverityBadge');
  const reasonEl = document.getElementById('simReasonText');

  if (scoreEl) scoreEl.textContent = `${scoreOutOfTen} / 10`;

  if (total >= 80) {
    if (scoreEl) scoreEl.style.color = '#f87171';
    if (badgeEl) {
      badgeEl.style.background = '#ef4444';
      badgeEl.textContent = '🔴 CRITICAL (4-Hour SLA Target)';
    }
    if (reasonEl) reasonEl.textContent = 'Critical threshold exceeded. Auto-escalated to Zonal Executive Engineer and SMS alert dispatched to rapid repair crew.';
  } else if (total >= 60) {
    if (scoreEl) scoreEl.style.color = '#fdba74';
    if (badgeEl) {
      badgeEl.style.background = '#f97316';
      badgeEl.textContent = '🟠 HIGH PRIORITY (24-Hour SLA Target)';
    }
    if (reasonEl) reasonEl.textContent = 'High severity assigned based on transit hazard and sensitive area proximity. Work order queued with priority.';
  } else {
    if (scoreEl) scoreEl.style.color = '#fde047';
    if (badgeEl) {
      badgeEl.style.background = '#eab308';
      badgeEl.textContent = '🟡 MEDIUM (72-Hour SLA Target)';
    }
    if (reasonEl) reasonEl.textContent = 'Standard grievance severity. Routed to local ward maintenance depot under regular routine queue.';
  }
}

